+.cell.center-bottom { border-bottom: 3px solid var(--center-border-color); }
+.cell.center-left { border-left: 3px solid var(--center-border-color); }
+.cell.center-right { border-right: 3px solid var(--center-border-color); }
+
+.cell.valid-move {
+  background-color: rgba(56, 189, 248, 0.15);
+  cursor: pointer;
+}
+
+.cell.valid-move:hover {
+  background-color: rgba(56, 189, 248, 0.35);
+  transform: scale(1.05);
+  z-index: 2;
+}
+
+.cell.valid-move::after {
+  content: '';
+  width: 8px;
+  height: 8px;
+  border-radius: 50%;
+  background-color: rgba(56, 189, 248, 0.6);
+}
+
+.cell.removable-piece {
+  background-color: rgba(234, 179, 8, 0.2);
+  cursor: pointer;
+  animation: pulse-removal 1.5s infinite;
+}
+
+.cell.removable-piece:hover {
+  background-color: rgba(244, 63, 94, 0.4);
+  transform: scale(1.08);
+  z-index: 2;
+}
+
+@keyframes pulse-removal {
+  0% { box-shadow: inset 0 0 0 0 rgba(234, 179, 8, 0.7); }
+  70% { box-shadow: inset 0 0 0 4px rgba(234, 179, 8, 0); }
+  100% { box-shadow: inset 0 0 0 0 rgba(234, 179, 8, 0); }
+}
+
+.cell.piece-x {
+  color: var(--player-x-color);
+}
+
+.cell.piece-o {
+  color: var(--player-o-color);
+}
+
+.cell.in-row-3 {
+  box-shadow: inset 0 0 6px rgba(168, 85, 247, 0.5);
+}
+
+.cell.in-row-4 {
+  box-shadow: inset 0 0 8px rgba(245, 158, 11, 0.8);
+}
+
+.cell.in-row-5 {
+  box-shadow: inset 0 0 10px rgba(34, 197, 94, 0.9);
+}
