+            </p>
+          </div>
+
+          <div class="card scoreboard-card">
+            <h2>Scoreboard</h2>
+            <div class="score-row player-x-score">
+              <span class="player-label">Player X</span>
+              <div class="score-details">
+                <div>Rows of 4: <strong id="x-rows-4">0</strong>/3</div>
+                <div>Rows of 5: <strong id="x-rows-5">0</strong>/1</div>
+                <div>Rows of 3: <span id="x-rows-3">0</span></div>
