+                <div>Rows of 5: <strong id="o-rows-5">0</strong>/1</div>
+                <div>Rows of 3: <span id="o-rows-3">0</span></div>
+              </div>
+            </div>
+          </div>
+
+          <div class="card controls-card">
+            <button id="reset-btn" class="btn primary-btn">New Game</button>
+            <a href="docs/RULES.md" target="_blank" class="rules-link">View Full Rules</a>
+          </div>
+        </aside>
+
+        <!-- Main Game Board -->
+        <section class="board-container">
+          <div id="board" class="grid-board"></div>
+        </section>
+      </div>
+    </main>
+  </div>
+
+  <script src="js/game.js"></script>
+  <script src="js/app.js"></script>
+</body>
+</html>
