+:root {
+  --bg-color: #0f172a;
+  --panel-bg: #1e293b;
+  --panel-border: #334155;
+  --text-main: #f8fafc;
+  --text-muted: #94a3b8;
+  --player-x-color: #38bdf8;
+  --player-o-color: #f43f5e;
+  --valid-move-color: rgba(56, 189, 248, 0.25);
+  --center-border-color: #f59e0b;
+  --removal-color: #eab308;
+  --cell-bg: #0f172a;
+  --cell-border: #1e293b;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+body {
+  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
+  background-color: var(--bg-color);
+  color: var(--text-main);
+  min-height: 100vh;
+  display: flex;
+  justify-content: center;
+  align-items: center;
+  padding: 20px;
+}
+
+.app-container {
+  max-width: 1200px;
+  width: 100%;
+  display: flex;
+  flex-direction: column;
+  gap: 20px;
+}
+
+header {
+  text-align: center;
+}
+
+header h1 {
+  font-size: 2.2rem;
+  font-weight: 700;
+  color: #f8fafc;
+}
+
+header .subtitle {
+  color: var(--text-muted);
+  font-size: 0.95rem;
+  margin-top: 5px;
+}
+
+.game-layout {
+  display: grid;
+  grid-template-columns: 320px 1fr;
+  gap: 24px;
+  align-items: start;
+}
+
+@media (max-width: 900px) {
+  .game-layout {
+    grid-template-columns: 1fr;
+  }
+}
+
+.sidebar {
+  display: flex;
+  flex-direction: column;
+  gap: 16px;
+}
+
+.card {
+  background-color: var(--panel-bg);
+  border: 1px solid var(--panel-border);
+  border-radius: 12px;
+  padding: 18px;
+}
+
+.card h2 {
+  font-size: 1.1rem;
+  margin-bottom: 12px;
+  color: var(--text-muted);
+  text-transform: uppercase;
+  letter-spacing: 0.05em;
+}
+
+.turn-indicator {
+  font-size: 1.25rem;
+  font-weight: bold;
+  padding: 8px 12px;
+  border-radius: 8px;
+  margin-bottom: 10px;
+  text-align: center;
+}
+
+.turn-indicator.player-x {
+  background-color: rgba(56, 189, 248, 0.15);
+  color: var(--player-x-color);
+  border: 1px solid var(--player-x-color);
+}
+
+.turn-indicator.player-o {
+  background-color: rgba(244, 63, 94, 0.15);
+  color: var(--player-o-color);
+  border: 1px solid var(--player-o-color);
+}
+
+.turn-indicator.removal-phase {
+  background-color: rgba(234, 179, 8, 0.15);
+  color: var(--removal-color);
+  border: 1px solid var(--removal-color);
+}
+
+.status-message {
+  font-size: 0.95rem;
+  line-height: 1.4;
+  color: var(--text-main);
